using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a web search tool that queries a public search API.
/// Uses the Brave Search API when configured, otherwise falls back to
/// a simple HTML scrape of lite.duckduckgo.com.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _http;
    private readonly string? _braveApiKey;

    public WebSearchTool(HttpClient httpClient, string? braveApiKey = null)
    {
        _http = httpClient;
        _braveApiKey = braveApiKey;
    }

    [Description("Search the web for information on a topic. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrWhiteSpace(_braveApiKey))
        {
            return await SearchWithBraveAsync(query, maxResults);
        }

        return await SearchWithDuckDuckGoAsync(query, maxResults);
    }

    private async Task<string> SearchWithBraveAsync(string query, int maxResults)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("Accept", "application/json");
        request.Headers.Add("X-Subscription-Token", _braveApiKey);

        var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<BraveSearchResponse>();
        if (json?.Web?.Results is null or { Count: 0 })
        {
            return "No results found.";
        }

        var results = json.Web.Results
            .Take(maxResults)
            .Select((r, i) => $"[{i + 1}] {r.Title}\n    URL: {r.Url}\n    {r.Description}");

        return string.Join("\n\n", results);
    }

    private async Task<string> SearchWithDuckDuckGoAsync(string query, int maxResults)
    {
        var url = $"https://lite.duckduckgo.com/lite/?q={Uri.EscapeDataString(query)}";
        var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("User-Agent", "ResearchAgent/1.0");

        var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync();
        var results = ParseDuckDuckGoResults(html, maxResults);

        return results.Count == 0
            ? "No results found."
            : string.Join("\n\n", results.Select((r, i) => $"[{i + 1}] {r.Title}\n    URL: {r.Url}\n    {r.Snippet}"));
    }

    private static List<DdgResult> ParseDuckDuckGoResults(string html, int max)
    {
        var results = new List<DdgResult>();
        var span = html.AsSpan();

        // DuckDuckGo Lite returns results as table rows with class "result-link" anchors
        const string linkMarker = "class=\"result-link\"";
        const string snippetMarker = "class=\"result-snippet\"";

        var pos = 0;
        while (results.Count < max && pos < span.Length)
        {
            var linkIdx = html.IndexOf(linkMarker, pos, StringComparison.Ordinal);
            if (linkIdx < 0) break;

            // Extract href
            var hrefStart = html.LastIndexOf("href=\"", linkIdx, StringComparison.Ordinal);
            string url = "", title = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                    url = html[hrefStart..hrefEnd];
            }

            // Extract title (text inside the anchor)
            var closeTag = html.IndexOf('>', linkIdx);
            if (closeTag >= 0)
            {
                var endAnchor = html.IndexOf("</a>", closeTag, StringComparison.Ordinal);
                if (endAnchor > closeTag)
                    title = StripHtml(html[(closeTag + 1)..endAnchor]).Trim();
            }

            // Extract snippet
            var snippet = "";
            var snippetIdx = html.IndexOf(snippetMarker, linkIdx, StringComparison.Ordinal);
            if (snippetIdx >= 0)
            {
                var sClose = html.IndexOf('>', snippetIdx);
                if (sClose >= 0)
                {
                    var sEnd = html.IndexOf("</td>", sClose, StringComparison.Ordinal);
                    if (sEnd < 0) sEnd = html.IndexOf("</span>", sClose, StringComparison.Ordinal);
                    if (sEnd > sClose)
                        snippet = StripHtml(html[(sClose + 1)..sEnd]).Trim();
                }
            }

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new DdgResult(title, url, snippet));
            }

            pos = linkIdx + linkMarker.Length;
        }

        return results;
    }

    private static string StripHtml(string input)
    {
        var chars = new char[input.Length];
        var ci = 0;
        var inTag = false;
        foreach (var c in input)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) chars[ci++] = c;
        }
        return new string(chars, 0, ci);
    }

    private sealed record DdgResult(string Title, string Url, string Snippet);

    // Brave Search API response models
    private sealed class BraveSearchResponse
    {
        [JsonPropertyName("web")]
        public BraveWebResults? Web { get; set; }
    }

    private sealed class BraveWebResults
    {
        [JsonPropertyName("results")]
        public List<BraveWebResult>? Results { get; set; }
    }

    private sealed class BraveWebResult
    {
        [JsonPropertyName("title")]
        public string Title { get; set; } = "";

        [JsonPropertyName("url")]
        public string Url { get; set; } = "";

        [JsonPropertyName("description")]
        public string Description { get; set; } = "";
    }
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities for the research agent.
/// Notes are stored in memory and can be saved, listed, and retrieved.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    [Description("Save a research note with a title and content. Use this to record key findings from web searches.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the note")] string content,
        [Description("Source URL, if applicable")] string? sourceUrl = null)
    {
        var note = new Note(
            Id: _notes.Count + 1,
            Title: title,
            Content: content,
            SourceUrl: sourceUrl,
            CreatedAt: DateTime.UtcNow);

        _notes.Add(note);
        return $"Note #{note.Id} saved: \"{title}\"";
    }

    [Description("List all saved research notes with their IDs and titles.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"Total notes: {_notes.Count}");
        foreach (var note in _notes)
        {
            sb.AppendLine($"  #{note.Id}: {note.Title}");
        }
        return sb.ToString();
    }

    [Description("Retrieve the full content of a specific note by its ID.")]
    public string GetNote([Description("The note ID to retrieve")] int noteId)
    {
        var note = _notes.Find(n => n.Id == noteId);
        if (note is null)
            return $"Note #{noteId} not found.";

        var sb = new StringBuilder();
        sb.AppendLine($"Note #{note.Id}: {note.Title}");
        sb.AppendLine($"Created: {note.CreatedAt:u}");
        if (!string.IsNullOrWhiteSpace(note.SourceUrl))
            sb.AppendLine($"Source: {note.SourceUrl}");
        sb.AppendLine();
        sb.Append(note.Content);
        return sb.ToString();
    }

    [Description("Get all notes formatted as a research summary with sources.")]
    public string GetAllNotesForSummary()
    {
        if (_notes.Count == 0)
            return "No notes have been saved. Perform searches and save notes first.";

        var sb = new StringBuilder();
        sb.AppendLine("=== Research Notes ===");
        sb.AppendLine();
        foreach (var note in _notes)
        {
            sb.AppendLine($"## {note.Title}");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrWhiteSpace(note.SourceUrl))
                sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public sealed record Note(
        int Id,
        string Title,
        string Content,
        string? SourceUrl,
        DateTime CreatedAt);
}

