toolArgs.new_str:
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// --- Configuration ---
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OpenAI API key via 'AI:ApiKey' in config or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

// Optional: Brave Search API key for higher-quality web search results
var braveApiKey = builder.Configuration["Search:BraveApiKey"]
    ?? Environment.GetEnvironmentVariable("BRAVE_API_KEY");

// --- Services ---
builder.Services.AddHttpClient();

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton(sp =>
    new WebSearchTool(sp.GetRequiredService<IHttpClientFactory>().CreateClient("search"), braveApiKey));

builder.Services.AddSingleton<NoteTool>();

using var host = builder.Build();

// --- Resolve services ---
var chatClient = host.Services.GetRequiredService<IChatClient>();
var searchTool = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();

// --- Build agent tools ---
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.ListNotes),
    AIFunctionFactory.Create(noteTool.GetNote),
    AIFunctionFactory.Create(noteTool.GetAllNotesForSummary),
};

// --- Configure agent ---
var agent = new ChatClientAgent(chatClient,
    """
    You are a research assistant. Your job is to thoroughly research a topic
    the user provides by following these steps:

    1. SEARCH: Use the SearchWebAsync tool to search for information. Perform
       multiple searches with different queries to get comprehensive coverage.

    2. TAKE NOTES: For each useful search result, use SaveNote to record key
       findings. Include the source URL when available.

    3. SYNTHESIZE: After gathering enough information (aim for 3-5 notes),
       use GetAllNotesForSummary to review your notes, then provide a
       well-structured summary to the user.

    Always cite your sources. Be thorough but concise.
    """,
    tools);

var agentOptions = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 Research Agent Ready        ║");
Console.WriteLine("║  Type a topic to research, or 'q'   ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("q", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching... (this may take a moment)");
    Console.ResetColor();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    try
    {
        Console.WriteLine();
        await foreach (var update in agent.InvokeStreamingAsync(history, agentOptions))
        {
            if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }
        }
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    // Show captured notes summary
    if (noteTool.Notes.Count > 0)
    {
        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine($"📝 {noteTool.Notes.Count} note(s) captured during research.");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

